package stream_probe

import (
	"context"
	"net"
	"os"
	"os/exec"
	"path/filepath"
	"sync"
	"testing"
	"time"

	bbspb "github.com/buildbuddy-io/buildbuddy/proto/buildbuddy_service"
	eventlogpb "github.com/buildbuddy-io/buildbuddy/proto/eventlog"
	invocationpb "github.com/buildbuddy-io/buildbuddy/proto/invocation"
	runnerpb "github.com/buildbuddy-io/buildbuddy/proto/runner"
	"google.golang.org/grpc"
	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/status"
)

// Run the actual pinned CLI against controlled log transport errors. No hosted
// build is started; Run only records requests and returns an observer identity.
type service struct {
	bbspb.UnimplementedBuildBuddyServiceServer
	mu                     sync.Mutex
	firstCode              codes.Code
	runs, streams, cancels int
}

func (s *service) Run(context.Context, *runnerpb.RunRequest) (*runnerpb.RunResponse, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.runs++
	if s.runs > 1 {
		return nil, status.Error(codes.InvalidArgument, "probe terminates a resubmission")
	}
	return &runnerpb.RunResponse{InvocationId: "11111111-1111-4111-8111-111111111111"}, nil
}

func (s *service) GetEventLog(_ *eventlogpb.GetEventLogChunkRequest, _ bbspb.BuildBuddyService_GetEventLogServer) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.streams++
	if s.streams == 1 {
		return status.Error(s.firstCode, "stream terminated by RST_STREAM with error code: INTERNAL_ERROR")
	}
	return status.Error(codes.InvalidArgument, "probe terminates a resumed observation")
}

func (s *service) CancelExecutions(context.Context, *invocationpb.CancelExecutionsRequest) (*invocationpb.CancelExecutionsResponse, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.cancels++
	return &invocationpb.CancelExecutionsResponse{}, nil
}

func TestPinnedCLILogTransportRetry(t *testing.T) {
	source, err := os.ReadFile(filepath.Join(os.Getenv("TEST_SRCDIR"), os.Getenv("PROBE_SOURCE_RLOCATION")))
	if err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(os.Getenv("TEST_UNDECLARED_OUTPUTS_DIR"), "stream_probe_test.go"), source, 0600); err != nil {
		t.Fatal(err)
	}
	for _, tc := range []struct {
		name                  string
		code                  codes.Code
		wantRuns, wantStreams int
	}{
		{"Internal resubmits the build", codes.Internal, 2, 1},
		{"Unavailable reconnects observation", codes.Unavailable, 1, 2},
	} {
		t.Run(tc.name, func(t *testing.T) {
			fixture := t.TempDir()
			for _, args := range [][]string{
				{"init", "--initial-branch=devel"},
				{"config", "user.name", "probe"},
				{"config", "user.email", "probe@example.invalid"},
				{"remote", "add", "origin", "https://github.com/example/probe"},
				{"config", "buildbuddy.remote-bazel-default-branch", "devel"},
				{"commit", "--allow-empty", "-m", "fixture"},
			} {
				cmd := exec.Command("git", args...)
				cmd.Dir = fixture
				if output, err := cmd.CombinedOutput(); err != nil {
					t.Fatalf("git %v: %v\n%s", args, err, output)
				}
			}
			if err := os.WriteFile(filepath.Join(fixture, "MODULE.bazel"), []byte("module(name = \"probe\")\n"), 0600); err != nil {
				t.Fatal(err)
			}
			listener, err := net.Listen("tcp", "127.0.0.1:0")
			if err != nil {
				t.Fatal(err)
			}
			server := grpc.NewServer()
			s := &service{firstCode: tc.code}
			bbspb.RegisterBuildBuddyServiceServer(server, s)
			go func() { _ = server.Serve(listener) }()
			t.Cleanup(server.Stop)
			binary := filepath.Join(os.Getenv("TEST_SRCDIR"), os.Getenv("BB_RLOCATION"))
			ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
			defer cancel()
			cmd := exec.CommandContext(ctx, binary, "remote", "--remote_runner=grpc://"+listener.Addr().String(), "--run_from_commit=0123456789012345678901234567890123456789", "--run_from_branch=devel", "build", "//:probe", "--remote_header=x-buildbuddy-api-key=probe")
			cmd.Dir = fixture
			output, err := cmd.CombinedOutput()
			if err == nil {
				t.Fatal("controlled terminal error unexpectedly succeeded")
			}
			s.mu.Lock()
			defer s.mu.Unlock()
			if s.runs != tc.wantRuns || s.streams != tc.wantStreams || s.cancels != 1 {
				t.Fatalf("Run=%d GetEventLog=%d CancelExecutions=%d, want %d/%d/1; CLI: %v\n%s", s.runs, s.streams, s.cancels, tc.wantRuns, tc.wantStreams, err, output)
			}
			t.Logf("pinned CLI: Run=%d GetEventLog=%d CancelExecutions=%d; expected probe exit: %v", s.runs, s.streams, s.cancels, err)
		})
	}
}
